function calculatePayback() {
  const price = parseFloat(document.getElementById('devicePrice').value) || 0;
  const subsidy = parseFloat(document.getElementById('subsidyAmount').value) || 0;
  const costPerRun = parseFloat(document.getElementById('costPerRun').value) || 0;
  const runs = parseFloat(document.getElementById('monthlyRuns').value) || 0;
  const filter = parseFloat(document.getElementById('annualFilterCost').value) || 0;
  const trashSaving = parseFloat(document.getElementById('monthlyTrashSaving').value) || 0;

  const netInitialCost = Math.max(0, price - subsidy);
  const annualElectricity = costPerRun * runs * 12;
  const annualRunningCost = annualElectricity + filter;
  const annualSaving = trashSaving * 12;
  const annualNetBalance = annualSaving - annualRunningCost;

  let headlineHtml = '';
  let paybackYearsText = '';

  if (annualNetBalance > 0) {
    const years = (netInitialCost / annualNetBalance).toFixed(1);
    paybackYearsText = years + '年';
    headlineHtml = '結論：約 <strong>' + years + '年</strong> で初期費用の元が取れます！';
  } else {
    const monthlyNetDeficit = Math.round(Math.abs(annualNetBalance) / 12);
    paybackYearsText = '金銭回収不可';
    headlineHtml = '結論：ゴミ袋代だけでは元は取れませんが、<strong>実質月額 ' + monthlyNetDeficit.toLocaleString() + '円</strong> で悪臭・コバエのない快適空間が買えます。';
  }

  const monthlyNetCost = Math.round(annualRunningCost / 12);

  const html = '<div class="result-headline">' + headlineHtml + '</div>' +
    '<div class="metrics-row">' +
      '<div class="metric-card"><span>実質本体負担額</span><strong>' + netInitialCost.toLocaleString() + '円</strong><small>助成金適用後</small></div>' +
      '<div class="metric-card"><span>年間ランニングコスト</span><strong>' + Math.round(annualRunningCost).toLocaleString() + '円</strong><small>電気代＋フィルター代</small></div>' +
      '<div class="metric-card"><span>年間ゴミ袋節約額</span><strong>' + Math.round(annualSaving).toLocaleString() + '円</strong><small>指定袋削減分</small></div>' +
      '<div class="metric-card"><span>回収判定（損益分岐）</span><strong>' + paybackYearsText + '</strong><small>' + (annualNetBalance > 0 ? '年間 ' + Math.round(annualNetBalance).toLocaleString() + '円 節約' : '月実質 ' + Math.round(Math.abs(annualNetBalance) / 12).toLocaleString() + '円 のQOL投資') + '</small></div>' +
    '</div>';

  document.getElementById('calcResult').innerHTML = html;
}
document.addEventListener('DOMContentLoaded', calculatePayback);
